files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #5f0dee;
}

.video-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
}

video {
  inline-size: 100%;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}

.video-list li:first-of-type video {
  -webkit-mask-image: url(../svg/ellipse-mask.svg);
  mask-image: url(../svg/ellipse-mask.svg);
}

.video-list li:nth-of-type(2) video {
  -webkit-mask-image: url(../svg/clover-mask.svg);
  mask-image: url(../svg/clover-mask.svg);
}

.video-list li:nth-of-type(3) video {
  -webkit-mask-image: url(../svg/heart-mask.svg);
  mask-image: url(../svg/heart-mask.svg);
}
